//! PR-B adversarial sweep — 44 edge-case fixtures generated by a 3-agent
//! workflow, each with a precise expected runtime result. Aggregates ALL
//! divergences into one report so a single run surfaces every bug.
//!
//! "neg" fixtures end every path in `return 0 - K` and trap; the decoded K is
//! the actual. "run_out" fixtures end in `s.as_output()`; the emitted bytes are
//! the actual.

use sigil_compiler::compile_tool;
use sigil_runtime::ephemeral::ToolError;
use sigil_runtime::execute_ephemeral;
use sigil_runtime::grants::IoGrants;

fn run_neg(body: &str) -> Result<String, String> {
    let src = format!(
        "module tool;\npub fn tool_main(input_ptr: i64, input_len: i64) -> i64 {{\n{body}\n}}\n"
    );
    let result = compile_tool(&src).map_err(|e| format!("COMPILE_ERR: {e:?}"))?;
    match execute_ephemeral(&result.wasm, b"", result.fuel_budget, &IoGrants::none()) {
        Err(ToolError::Trapped { message }) => {
            let p = "tool returned error (";
            match message.find(p) {
                Some(i) => {
                    let s = i + p.len();
                    let e = message[s..].find(')').ok_or("no-close-paren")?;
                    Ok(message[s..s + e].to_string())
                }
                None => Err(format!("TRAP_NO_SENTINEL: {message}")),
            }
        }
        Ok(_) => Err("NO_TRAP (returned non-negative)".to_string()),
        Err(other) => Err(format!("EXEC_ERR: {other:?}")),
    }
}

fn run_out(body: &str) -> Result<String, String> {
    let src = format!(
        "module tool;\npub fn tool_main(input_ptr: i64, input_len: i64) -> i64 ! {{ Alloc }} {{\n{body}\n}}\n"
    );
    let result = compile_tool(&src).map_err(|e| format!("COMPILE_ERR: {e:?}"))?;
    match execute_ephemeral(&result.wasm, b"", result.fuel_budget, &IoGrants::none()) {
        Ok(exec) => String::from_utf8(exec.output).map_err(|e| format!("NON_UTF8: {e}")),
        Err(other) => Err(format!("EXEC_ERR: {other:?}")),
    }
}

