#[test]
fn pr_b_adversarial_sweep() {
    let mut failures: Vec<String> = Vec::new();
    for (i, (kind, body, expected)) in FIXTURES.iter().enumerate() {
        let actual = match *kind {
            "neg" => run_neg(body),
            "out" => run_out(body),
            other => panic!("bad kind {other}"),
        };
        match actual {
            Ok(got) if got == *expected => {}
            Ok(got) => failures.push(format!(
                "[#{i} {kind}] MISMATCH expected={expected:?} got={got:?}\n  body: {body}"
            )),
            Err(why) => failures.push(format!(
                "[#{i} {kind}] {why}\n  expected={expected:?}\n  body: {body}"
            )),
        }
    }
    if !failures.is_empty() {
        panic!(
            "\n{} of {} adversarial fixtures diverged:\n\n{}\n",
            failures.len(),
            FIXTURES.len(),
            failures.join("\n\n")
        );
    }
}
